/// <summary>
/// AVA_008345_AssetAssuranceValue
/// </summary>
internal final class AVAAssetCalcInsValueService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// AVA_008345_AssetAssuranceValue
/// </summary>
public void process()
{
    AssetTable          assetTable;
    int                 counter;
    AssetInsuredValue   oldValue;

    ttsbegin;
    while select forupdate assetTable
    {
        oldValue = assetTable.InsuredValue;
        assetTable.InsuredValue = assetTable.AVAcalcInsuredValue();
        if (!assetTable.KCS_FABAssetManualInsValue && assetTable.InsuredValue != oldValue)
        {
            //no validate, because InsuredValue not part of validation();
            assetTable.validateWrite();
            assetTable.update();
            counter++;
        }
    }
    ttscommit;

    info(strfmt("@FAB110",counter));
}
